ALTER POLICY "tenant" ON "project_invites" TO public USING ("project_invites"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("project_invites"."org_id" is not null or exists (select 1 from "projects" where "projects"."id" = "project_invites"."project_id") or "project_invites"."email" = lower(current_setting('app.user_email', true)))) WITH CHECK ("project_invites"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("project_invites"."org_id" is not null or exists (select 1 from "projects" where "projects"."id" = "project_invites"."project_id")));